/**
 * Draft cards without saving anything.
 *
 * The chat model does not write the cards itself. It decides what is wanted and
 * calls this; the cards are generated by the one-shot functions the app already
 * uses, on the cheap model. That is what keeps a built lesson at fractions of a
 * cent instead of eight (spec §9.2) — the long structured output never passes
 * through the chat model's output price.
 *
 * Nothing here touches the database. The draft goes to the person as a
 * `show_card_drafts` component, and only what they tick is ever saved.
 *
 * Questions are not generated here. `generate-questions` verifies its lesson and
 * card ids against the database, so it cannot run on cards that do not exist yet;
 * practice questions are made after the cards land.
 */

import { z } from 'npm:zod@^4.3.6';

export const draftLessonInput = z.object({
  topic: z.string().trim().min(1).max(2000)
    .describe('What the cards should cover, in the person’s own words.'),
  learning_mode: z.enum(['knowledge', 'language']).default('knowledge')
    .describe('Use language for learning a language, knowledge for everything else.'),
  card_count: z.number().int().min(1).max(50).optional()
    .describe('Roughly how many cards. Advisory: the generator decides the final number from the material.'),
}).strict();

export type DraftLessonArgs = z.output<typeof draftLessonInput>;

/** The extra a language card carries: how it sounds, how it is used, what it
 *  belongs with. Shaped like `terms.language_data`, because that is where it ends
 *  up. Kept loose here — the generator owns the shape, and this only carries it. */
export type LanguageDetails = Record<string, unknown>;

export type DraftCard = {
  /** Local to this draft and stable within it; what a selection refers to. Not a
   *  database id, because nothing has been written. */
  id: string;
  term: string;
  definition: string;
  explanation?: string | null;
  /** Language mode only. Never sent to the model — see `slimForModel`. */
  language_data?: LanguageDetails | null;
};

export type DraftResult = {
  cards: DraftCard[];
  learning_mode: 'knowledge' | 'language';
  /** Echoed back so the model can name the lesson from what was actually asked. */
  topic: string;
};

export type DraftContext = {
  fetch: typeof fetch;
  /** e.g. https://<project>.supabase.co/functions/v1 */
  functionsUrl: string;
  /** The caller's own bearer token: generation runs with their privileges, not ours. */
  authorization: string;
};

type GeneratedTerm = {
  term?: unknown;
  definition?: unknown;
  explanation?: unknown;
  language_data?: unknown;
};

/** The same two generators the create screen picks between, so a card drafted in
 *  chat is the same kind of card as one drafted there. */
export function generatorFor(mode: 'knowledge' | 'language'): string {
  return mode === 'language' ? 'generate-vocab-terms' : 'generate-terms';
}

export async function draftLesson(args: DraftLessonArgs, ctx: DraftContext): Promise<DraftResult> {
  const mode = args.learning_mode;
  // The generators take free text and decide the count themselves, so a requested
  // number can only be asked for, not set.
  const content = args.card_count
    ? `${args.topic}\n\n(About ${args.card_count} cards.)`
    : args.topic;

  const response = await ctx.fetch(`${ctx.functionsUrl}/${generatorFor(mode)}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: ctx.authorization },
    body: JSON.stringify({ type: 'topic', content }),
  });

  if (!response.ok) {
    // Say what the person can act on, not what the provider said.
    throw new Error('Could not draft cards just now. Try again, or say it a different way.');
  }

  let payload: { results?: unknown };
  try {
    payload = await response.json();
  } catch {
    throw new Error('Could not draft cards just now. Try again, or say it a different way.');
  }

  const raw = Array.isArray(payload.results) ? payload.results as GeneratedTerm[] : [];
  const cards: DraftCard[] = [];
  for (const item of raw) {
    if (!item || typeof item.term !== 'string' || typeof item.definition !== 'string') continue;
    const term = item.term.trim();
    const definition = item.definition.trim();
    if (!term || !definition) continue;
    const explanation = typeof item.explanation === 'string' && item.explanation.trim()
      ? item.explanation.trim() : null;
    const details = item.language_data && typeof item.language_data === 'object' && !Array.isArray(item.language_data)
      ? item.language_data as LanguageDetails : null;
    cards.push({ id: `d${cards.length + 1}`, term, definition, explanation, language_data: details });
    // The component draws at most this many, and a draft nobody can read is no use.
    if (cards.length >= 50) break;
  }

  if (!cards.length) {
    throw new Error('Nothing useful came out of that. Ask for something more specific, or give more detail.');
  }

  return { cards, learning_mode: mode, topic: args.topic };
}

/**
 * The draft as the model should see it: no language details.
 *
 * The details are long — pronunciation, forms, example, synonyms, collocations —
 * and the model has no use for them. Sending them would mean paying for them twice
 * at the chat model's prices: once reading the tool result, and again when the
 * model echoes every field back into `show_card_drafts`. That is exactly the long
 * structured output the thin tool was built to avoid (spec §9.2).
 *
 * So they stay on this side. `draft_lesson` and `show_card_drafts` happen in one
 * request, so the function can hold them and put them back by id before the
 * component goes out.
 */
export function slimForModel(result: DraftResult): DraftResult {
  return {
    ...result,
    cards: result.cards.map(({ language_data: _details, ...rest }) => rest),
  };
}

/** The details from a draft, by card id, for putting back later. */
export function detailsById(result: DraftResult): Map<string, LanguageDetails> {
  const details = new Map<string, LanguageDetails>();
  for (const card of result.cards) {
    if (card.language_data) details.set(card.id, card.language_data);
  }
  return details;
}

/**
 * Put the language details back into what the model asked to show.
 *
 * Matched by id, so a model that drops a card, reorders them or shows only some
 * still gets the right details on the right cards. A card whose id is not in the
 * draft simply keeps none — an invented id cannot pull in someone else's detail.
 */
export function withDetails(props: unknown, details: Map<string, LanguageDetails>): unknown {
  if (!details.size || !props || typeof props !== 'object') return props;
  const value = props as Record<string, unknown>;
  if (!Array.isArray(value.cards)) return props;
  return {
    ...value,
    cards: value.cards.map((card) => {
      if (!card || typeof card !== 'object') return card;
      const entry = card as Record<string, unknown>;
      const found = typeof entry.id === 'string' ? details.get(entry.id) : undefined;
      return found ? { ...entry, language_data: found } : entry;
    }),
  };
}
